   133  void RawPacket::insertData(int atIndex, const uint8_t* dataToInsert, size_t dataToInsertLen)
   134  {
   135          // memmove copies data as if there was an intermediate buffer in between - so it allows for copying processes on overlapping src/dest ptrs
   136          // if insertData is called with atIndex == m_RawDataLen, then no data is being moved. The data of the raw packet is still extended by dataToInsertLen
   137          memmove((uint8_t*)m_RawData + atIndex + dataToInsertLen, (uint8_t*)m_RawData + atIndex, m_RawDataLen - atIndex);
   138
