   141                  // insert data
   142                  memcpy((uint8_t*)m_RawData + atIndex, dataToInsert, dataToInsertLen);
   143          }
   144
   145          m_RawDataLen += dataToInsertLen;
   146          m_FrameLength = m_RawDataLen;
